#!/usr/bin/env bash
# Mac-side deploy settings for stark, then web/scripts/deploy.sh: web/scripts/deploy-app.sh <user@host> [--check]
# Generated by the new-web-app skill; web/scripts/deploy.sh itself stays generic.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ADDR_LINE="$(grep '^ADDR=' "$HERE/../deploy/.env.example" || true)"
PORT="${ADDR_LINE##*:}"
case "$PORT" in
  ""|*[!0-9]*)
    echo "deploy-app: the app's port is not set. Pick a free port on the server (ss -tln, then ps aux), then set ADDR=0.0.0.0:<port> in web/deploy/.env.example and in the server .env, and the same port in the DreamHost panel Proxy Server. Nothing was changed." >&2
    exit 1 ;;
esac
export PUBLIC_URL=https://stark.caritos.com
export EXPECT_PUBLIC_LISTENER=1
# deploy.sh refuses to deploy unless ${SERVICE}-backup.timer is enabled on the server
export REQUIRE_BACKUP_TIMER=1
# smoke.sh looks for this text in the home page HTML, so it is the HTML-escaped display name
export APP_NAME='Stark'
# Stark is a static marketing site: the starter's React app is not built or embedded (2026-11-01), so
# deploy.sh checks for the synced home page instead of the React index, and smoke.sh wants /app/ to be 404.
export EMBED_INDEX="$HERE/../api/embed/pages/index.html"
export SMOKE_APP=0
exec bash "$HERE/deploy.sh" "$@"
